package com.mythix.tcg.admin.api; import com.mythix.tcg.user.persistence.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin/users") @RequiredArgsConstructor public class AdminUsersController {private final UserRepository users; @GetMapping public List<AdminUserResponse> list(@RequestParam(defaultValue="") String search){return users.findByEmailContainingIgnoreCaseOrFullNameContainingIgnoreCaseOrderByCreatedAtDesc(search,search).stream().map(AdminUserResponse::from).toList();} @PatchMapping("/{id}/promote") public AdminUserResponse promote(@PathVariable Long id){var u=users.findById(id).orElseThrow();u.setRole("ADMIN");return AdminUserResponse.from(u);}}
